custom_css:
/* === 春日低语 感谢代码楼里老师们的代码https://discord.com/channels/1291925535324110879/1380392618336194702
感谢尾老师，类名，输入框伪提示词来自尾老师，hy老师的去除思维链箭头，na老师的悬浮底栏和思维链文字自定义，楼层信息自定义，12老师的去思维链背景色。感谢NA老师的去阴影，感谢咩野老师的去除全局阴影 === */

/* --- 1. 字体导入 --- */
@import url('https://fonts.googleapis.com/css2?family=Caveat:wght@400..700&display=swap'); 
@import url("https://fontsapi.zeoseven.com/881/main/result.css"); 
@import url("https://fontsapi.zeoseven.com/45/main/result.css");  
@import url("https://fontsapi.zeoseven.com/249/main/result.css"); 
@import url("https://fontsapi.zeoseven.com/2130/main/result.css"); 

/* --- 2. 核心颜色与样式变量 --- */
:root {
    --theme-bg-color: #E8F5E9; 
    --theme-bg-mid: #A5D6A7; 
    --card-bg: #FAFDFA; 
    --accent-green: #66BB6A; 
    --accent-yellow: #FFCA28; 
    --accent-dark: #388E3C; 
    --text-main: #2E4C16; 
    --text-subtle: #5C804B; 

    --font-english: 'Caveat', cursive;
    --font-main: "Jigmo", var(--font-english), sans-serif;
    --font-quote: "Long Cang", var(--font-english), serif;
    --font-code: "nzgrRuYinZouZhangKai", monospace;
    --font-title: "ZT ZiYouTi", var(--font-english), sans-serif;
}

/* --- 3. 全局样式与无阴影无边框设定 --- */
* { box-shadow: none !important; border-style: none !important; }
body { 
    background-color: var(--theme-bg-color) !important; 
    background-image: url('https://images.unsplash.com/photo-1464692805480-a69dfaafdb0d?q=80&w=2070&auto=format&fit=crop'); 
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: var(--text-main); 
    font-family: var(--font-main); 
    font-weight: normal; 
}
/* 春日阳光遮罩层 */
body::after {
    content: ''; position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
    background: radial-gradient(circle at top left, rgba(255, 255, 255, 0.5), transparent 60%);
    pointer-events: none; z-index: 9999; mix-blend-mode: overlay;
}

#sheld, #character_view { background: transparent !important; margin: 0 auto !important; left: 0; right: 0; border: none !important; overflow: visible !important; }
#chat { background: transparent !important; align-items: center !important; padding-bottom: 120px !important; }
h1, h2, h3, h4, .standoutHeader, .inline-drawer-header, .title_restorable { font-family: var(--font-title); color: var(--accent-dark); font-weight: normal; letter-spacing: 2px; }

/* --- 4. 导航栏贴图替换 --- */
#top-settings-holder { position:relative; background-color: rgba(240, 248, 234, 0.6); backdrop-filter: blur(10px); border: none !important; }
.drawer-icon.fa-fw::before { content: '' !important; font-size: 0 !important; }
.drawer-icon.fa-fw { width: 38px; height: 38px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1); }
.drawer-icon.fa-fw:hover { transform: translateY(-4px) scale(1.1) rotate(8deg); }

.drawer-icon.fa-sliders, #ai-config-button .drawer-icon, .drawer-icon.fa-user, #user-settings-button .drawer-icon, .drawer-icon.fa-cubes, #extensions-settings-button .drawer-icon, .drawer-icon.fa-face-smile, #persona-management-button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/HAfi/405X388/_%E7%BC%96%E7%BB%84_.png/webp'); 
}
.drawer-icon.fa-plug, #sys-settings-button .drawer-icon, .drawer-icon.fa-font, #advanced-formatting-button .drawer-icon, .drawer-icon.fa-book-atlas, #WI-SP-button .drawer-icon, .drawer-icon.fa-image, .drawer-icon.fa-panorama, .drawer-icon.fa-bars-progress, #table_database_settings_drawer .drawer-icon, .drawer-icon.fa-address-card, #character_popup_button .drawer-icon {
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/7vcY/397X388/_%E7%BC%96%E7%BB%842_.png/webp'); 
}

.drawer-content, dialog.popup .popup-body, #dialogue_popup {
    background-image: linear-gradient(rgba(250, 253, 250, 0.8), rgba(250, 253, 250, 0.9)), url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/vBp6/1200X811/d128075c58738f2ade425a5a8edbed1d.jpg/webp') !important;
    background-size: cover; background-position: center;
    border-radius: 16px !important; color: var(--text-main) !important;
}

/* --- 5. 底部悬浮输入栏 --- */
#send_textarea::placeholder { color: transparent !important; opacity: 0 !important; }
#send_textarea::-webkit-input-placeholder { color: transparent !important; opacity: 0 !important; }
#form_sheld { position: absolute !important; bottom: 20px !important; left: 0; right: 0; display: flex; justify-content: center; z-index: 1000; pointer-events: none; }
#send_form { 
    pointer-events: auto; width: 85% !important; max-width: 800px !important; margin: 0 auto !important; 
    background-color: rgba(255, 255, 255, 0.8) !important; padding: 12px 20px !important; 
    backdrop-filter: blur(15px) !important; -webkit-backdrop-filter: blur(15px) !important; 
    border-radius: 30px !important; transition: all 0.5s ease !important; position: relative;
    animation: float-spring 6s ease-in-out infinite;
}
@keyframes float-spring { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }

#rightSendForm, #leftSendForm { gap: 15px; }
#send_textarea { clip-path: none !important; border: none !important; background: transparent !important; color: var(--text-main) !important; }

#nonQRFormItems:has(#send_textarea:placeholder-shown)::before { 
    content: 'Baa~ Whispering to the spring breeze... 🐑🌿'; 
    color: var(--accent-green); position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); 
    font-family: var(--font-english); font-size: clamp(1rem, 2.5vw, 1.4rem); 
    pointer-events: none; z-index: 10; white-space: nowrap; 
    opacity: 0.7; animation: breeze-breathe 3s infinite alternate;
}
@keyframes breeze-breathe { 0% { opacity: 0.5; transform: translate(-50%, -50%) scale(0.98); } 100% { opacity: 0.9; transform: translate(-50%, -50%) scale(1.02); } }

#options_button::before, #send_but::before, #send_form #extensionsMenuButton::before, #ai_retry_button::before, #auto_completion_button::before { display: none !important; }
#options_button, #send_but, #send_form #extensionsMenuButton, #ai_retry_button, #auto_completion_button { width: 42px; height: 42px; background-size: contain; background-repeat: no-repeat; background-position: center; transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275); font-size: 0; background-color: transparent; }
#options_button:hover, #send_but:hover, #send_form #extensionsMenuButton:hover, #ai_retry_button:hover, #auto_completion_button:hover { transform: scale(1.15) translateY(-3px) rotate(-8deg); }

#options_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/k74O/1239X1813/%E7%BB%84_2.png/webp'); }
#send_but { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/k74O/1239X1813/%E7%BB%84_2.png/webp'); }
#send_form #extensionsMenuButton { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/tlw1/1052X1094/%E7%BB%84_12.png/webp'); }
#ai_retry_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/tlw1/1052X1094/%E7%BB%84_12.png/webp'); filter: hue-rotate(45deg); }
#auto_completion_button { background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/tlw1/1052X1094/%E7%BB%84_12.png/webp'); filter: hue-rotate(-45deg); }

/* --- 6. 核心：重构消息框结构与顶部横幅 --- */
.mes { 
    display: flex; flex-direction: column; 
    padding: 0 !important; 
    margin: 150px auto 50px !important; 
    width: 90%; max-width: 800px; 
    background-color: var(--card-bg) !important;
    border-radius: 12px !important; 
    backdrop-filter: blur(8px) !important;
    -webkit-backdrop-filter: blur(8px) !important;
    overflow: visible !important;
    position: relative; z-index: 10;
}

/* 🌟 层级修改一：背景横幅优先级提高 (z-index:20)，遮盖小信封的下边缘 */
.mes .mesAvatarWrapper {
    display: block; padding: 0;
    width: 100%; height: 140px !important; min-height: 140px !important;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/5yu7/1199X582/eb7450d01489a7d8980083a9f1e69aee.jpg/webp');
    background-size: cover; background-position: center; background-repeat: no-repeat;
    position: relative; z-index: 20 !important; /* 关键修改 */
    overflow: visible !important;
    border-top-left-radius: 12px; border-top-right-radius: 12px;
}

/* 🌟 层级修改二：头像保持全局最高优先级 (z-index:30) */
.mes .avatar {
    position: absolute;
    top: -30px; 
    width: 95px; height: 95px; 
    background: #fff !important; 
    padding: 6px !important; 
    z-index: 30 !important; /* 关键修改 */
    display: flex !important; align-items: center; justify-content: center;
    border-radius: 50% !important; 
    box-shadow: none !important;
}
.mes[is_user="false"] .avatar { left: 25px; transform: rotate(-5deg); }
.mes[is_user="true"] .avatar { right: 25px; left: auto; transform: rotate(5deg); }
.mes .avatar img { width: 100% !important; height: 100% !important; object-fit: cover !important; border-radius: 50% !important; }

/* --- 7. 彻底独立的名字与楼层信息 (小信封模块) --- */
.mes .mesAvatarWrapper > .ch_name { display: none !important; }

/* 🌟 层级修改三：主体区优先级降至(z-index:10)，让信封滑入横幅背后 */
.mes .mes_block { background-color: transparent !important; background-image: none !important; padding: 30px 35px 40px 35px !important; position: relative; border: none !important; overflow: visible !important; min-height: 100px !important; z-index: 10 !important; /* 关键修改 */ }

/* 信封位置设定 (top:-180px 让信封底部恰好有10多px插在背景图下方，形成立体的被遮挡感) */
.mes .mes_block > .ch_name { 
    display: inline-flex !important; position: absolute; 
    top: -180px !important; 
    width: auto !important; max-width: 60%;
    align-items: center !important; justify-content: center !important;
    background: #fff !important; 
    z-index: 100; padding: 10px 25px !important; 
    border-radius: 8px !important;
    border: 2px dashed var(--accent-green) !important;
    gap: 15px !important;
    animation: spring-breeze 4s infinite ease-in-out alternate;
}

/* 完美避开头像间距 */
.mes[is_user="false"] .mes_block > .ch_name { left: 135px !important; right: auto !important; flex-direction: row !important; transform-origin: left bottom; }
.mes[is_user="true"] .mes_block > .ch_name { right: 135px !important; left: auto !important; flex-direction: row-reverse !important; transform-origin: right bottom; }

.mes .mes_block > .ch_name::after { content: '✉️🍃'; font-size: 18px; position: absolute; top: -12px; right: -10px; z-index: 101; }
.mes[is_user="true"] .mes_block > .ch_name::after { left: -10px; right: auto; transform: scaleX(-1); }

@keyframes spring-breeze { 0% { transform: translateY(0) rotate(0deg); } 100% { transform: translateY(-3px) rotate(1deg); } }

.mes .ch_name .name_text { font-family: var(--font-english); font-size: 26px !important; color: var(--accent-dark) !important; font-weight: bold; }
.mes .mesIDDisplay, .mes .mes_timer { position: static !important; color: var(--text-subtle) !important; font-size: 16px !important; font-family: var(--font-english); background: transparent !important; border: none !important; }
.mesIDDisplay::before { content: 'Leaf No. '; color: var(--accent-green); }
.mesIDDisplay::after { content: ' 🐑'; }

/* --- 8. 消息主体区与新装饰贴图 --- */
.mes .mes_text, .mes_reasoning { background: transparent !important; border: none !important; padding: 0 !important; margin: 0 !important; backdrop-filter: none !important; position: relative; z-index: 2; }

.mes[is_user="false"] .mes_block::before {
    content: ''; position: absolute; bottom: -20px; left: -25px;
    width: 100px; height: 100px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/THzP/1141X1129/%E7%BB%84_5.png/webp');
    background-size: contain; background-repeat: no-repeat; background-position: center;
    z-index: 0; pointer-events: none; 
    animation: sheep-jump 3s infinite cubic-bezier(0.28, 0.84, 0.42, 1) alternate;
}
.mes[is_user="true"] .mes_block::before {
    content: ''; position: absolute; bottom: -20px; right: -25px;
    width: 120px; height: 80px;
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/15f4/1465X989/%E7%BB%84_9.png/webp');
    background-size: contain; background-repeat: no-repeat; background-position: center;
    z-index: 0; pointer-events: none;
    animation: sheep-jump 3.5s infinite cubic-bezier(0.28, 0.84, 0.42, 1) alternate-reverse;
}
@keyframes sheep-jump { 0% { transform: translateY(0) rotate(-2deg); } 100% { transform: translateY(-8px) rotate(3deg); } }

.mes_block::after {
    content: 'SPRING WHISPERS \A GREEN MEADOWS'; white-space: pre;
    position: absolute; top: 15px; color: rgba(165, 214, 167, 0.5);
    font-family: var(--font-english); font-size: 16px; text-align: center;
    border: 2px solid rgba(165, 214, 167, 0.4); border-radius: 50%;
    padding: 10px; z-index: 1; pointer-events: none;
}
.mes[is_user="false"] .mes_block::after { right: 30px; transform: rotate(15deg); }
.mes[is_user="true"] .mes_block::after { left: 30px; transform: rotate(-15deg); }

#chat .mes .mes_reasoning_header { background: transparent !important; border: none !important; border-radius: 0; backdrop-filter: none !important; padding: 0 !important; margin-bottom: 12px !important; display: inline-flex !important; align-items: center !important; }
.mes_reasoning_arrow { display: none !important; }
.mes_reasoning_header h4, .mes_reasoning_header_title { font-size: 0 !important; visibility: hidden; }
.mes_reasoning_header h4::before, .mes_reasoning_header_title::before { 
    content: "🌱 Grazing on spring thoughts... (Thinking)"; 
    font-family: var(--font-english); font-size: 20px !important; 
    color: var(--accent-dark); visibility: visible; letter-spacing: 1px; 
}
.mes_reasoning { padding-left: 15px !important; margin-bottom: 25px !important; color: var(--text-subtle); font-family: var(--font-quote); font-size: 1.1em; position: relative; }
.mes_reasoning::before { 
    content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 4px; border-radius: 2px;
    background: repeating-linear-gradient(45deg, var(--theme-bg-mid), var(--theme-bg-mid) 8px, transparent 8px, transparent 16px);
}
.mes .mes_text { line-height: 2.2; color: var(--text-main); font-size: 16px; text-align: justify; }

.mes .mes_buttons, .mes .mes_edit_buttons { flex-direction: row-reverse; gap: 8px; opacity: 0.1; transition: opacity 0.3s ease; pointer-events: auto !important; margin-top: 15px; }
.mes:hover .mes_buttons, .mes:hover .mes_edit_buttons { opacity: 1; }
.mes .mes_buttons .mes_button, .mes .mes_edit_buttons .mes_button { background-color: rgba(232, 245, 233, 0.8) !important; color: var(--accent-dark) !important; padding: 6px !important; border-radius: 50% !important; cursor: pointer; transition: all 0.2s ease; font-size: 14px !important; }
.mes .mes_buttons .mes_button:hover, .mes .mes_edit_buttons .mes_button:hover { background-color: var(--accent-yellow) !important; color: var(--text-main) !important; transform: scale(1.15) rotate(10deg); }

#typing_indicator { 
    background-image: url('https://tc-new.z.wiki/autoupload/1N2_UJVYUo2KjM-_22IFnCfNcKcqEnRmcljopnyJoMs/20260428/Q6yd/1028X1029/%E7%BB%84_6.png/webp') !important; 
    background-size: contain !important; background-repeat: no-repeat !important; background-position: center !important; 
    animation: sheep-jump 1.2s infinite alternate; 
    border: none !important; height: 50px !important; width: 50px !important; margin: 10px auto !important; 
}
#typing_indicator .dot { display: none !important; }

/* --- 9. 全局UI设定 (无边框清新风) --- */
.standoutHeader, .inline-drawer-header, .title_restorable, #extensions_settings2 > div, #extensions_settings > div, .openai_logit_bias_preset_form, details > summary, #power-user-options-block h4, #InstructSettingsColumn h4, #SystemPromptColumn h4, #ContextSettings h4, .persona_management_global_settings h4, #character_popup h4, #AdvancedFormatting h4, #rm_group_chats_block h4, div[name*='HandlingToggles'] h4, div[name*='MiscellaneousToggles'] h4 { background: rgba(255, 255, 255, 0.6) !important; border-radius: 8px !important; padding: 10px 15px !important; margin-bottom: 8px !important; color: var(--accent-dark) !important; }
input[type="text"], input[type="number"], input[type="search"], textarea, select, .text_pole { background-color: rgba(255,255,255,0.8) !important; color: var(--text-main) !important; border-radius: 8px !important; padding: 8px !important; }
input:focus, textarea:focus, select:focus { outline: 2px dashed var(--accent-green) !important; background-color: rgba(255,255,255,1) !important; }
.menu_button { background-color: rgba(255, 255, 255, 0.6) !important; color: var(--text-subtle) !important; transition: all 0.3s ease; border-radius: 8px !important; }
.menu_button:hover { background-color: var(--accent-green) !important; color: white !important; }
input[type="checkbox"]:checked::before { box-shadow: inset 1em 1em var(--accent-yellow) !important; }

dialog.popup { background-color: transparent !important; }
dialog.popup .popup-body::before, #dialogue_popup::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background-color: rgba(250, 253, 250, 0.85); z-index: 0; border-radius: 16px; }
dialog.popup .popup-body > *, #dialogue_popup > * { position: relative; z-index: 1; }
.menu_button.active, .menu_button.world_set, .menu_button.fav_on, #left-nav-panel .menu_button.selected { background-color: var(--accent-yellow) !important; color: var(--text-main) !important; }

/* --- 10. 手机端自适应调整 --- */
@media (max-width: 768px) {
    .mes { margin: 130px auto 40px !important; }
    .mes[is_user="false"] .mes_block::before, .mes[is_user="true"] .mes_block::before { width: 70px; height: 70px; bottom: -10px; }
    .mes .avatar { width: 75px; height: 75px; top: -20px; }
    .mes .ch_name .name_text { font-size: 20px !important; }
    .mes .mesAvatarWrapper { height: 110px !important; min-height: 110px !important; }

    /* 手机端同样通过 z-index 让信封滑入背后 */
    .mes .mes_block > .ch_name { top: -140px !important; padding: 6px 15px !important; gap: 8px !important; width: fit-content !important; min-width: 120px; }
    .mes[is_user="false"] .mes_block > .ch_name { left: 95px !important; }
    .mes[is_user="true"] .mes_block > .ch_name { right: 95px !important; }

    .mes .mesIDDisplay, .mes .mes_timer { font-size: 13px !important; }
}

#dialogue_popup { z-index: 10000 !important; pointer-events: auto !important; }
#dialogue_del_mes_ok, #dialogue_del_mes_cancel { background-color: rgba(255,255,255,0.9) !important; color: var(--accent-dark) !important; border-radius: 8px !important; padding: 10px 20px !important; margin: 10px 5px !important; transition: all 0.3s ease !important; }
#dialogue_del_mes_ok:hover { background-color: var(--accent-yellow) !important; color: var(--text-main) !important; transform: scale(1.05) rotate(2deg) !important; }
#dialogue_del_mes_cancel:hover { background-color: var(--theme-bg-mid) !important; color: #fff !important; transform: scale(1.05) !important; }
